   x.call("D29 conc efetivar100 par"+rep,"POST",j.pe(pe)+"/efetivacao",m("versao",j.pv(pe),"aceitarDivergencias",false,"motivo",x.round+" estoque100par"+rep),"SUPERVISOR",200);
