   var a=j.order("A"+rep,80);var b=j.order("B"+rep,80);orders.add(a.path("id").asLong());orders.add(b.path("id").asLong());x.ids.put("concorrenciaPedidos",orders);x.save();var da=x.version(a);var db=x.version(b);
