   var live=j.get(j.ps(winner));var loss=j.get(j.ps(loser));x.assertion("D29 conc par"+rep+" umreservado outrosemefeitos",live.path("situacao").asString().equals("RESERVADO")&&live.path("reservas").size()==1&&live.path("reservas").get(0).path("quantidade").decimalValue().intValueExact()==80&&loss.path("situacao").asString().equals("RASCUNHO")&&loss.path("reservas").isEmpty(),"RESERVADO80/RASCUNHO0",m("winner",live,"loser",loss));
