   var replay=pair("REPLAY"+rep,List.of(j.ps(winner)+"/reserva",j.ps(winner)+"/reserva"),List.of(cmd,cmd),false);x.assertion("D29 conc controle200200snapshot unico par"+rep,replay.get(0).equals(winningResponse)&&replay.get(1).equals(winningResponse)&&j.balance().equals(balance),winningResponse,replay);j.get(j.ps(winner));j.get(j.ps(loser));
