 List<JsonNode> pair(String name,List<String>routes,List<Map<String,Object>>bodies,boolean competition)throws Exception{
  var ready=new CountDownLatch(2);var start=new CountDownLatch(1);var timings=Collections.synchronizedList(new ArrayList<Map<String,Object>>());String jwt=x.token("OPERACAO",Map.of());
  try(var pool=Executors.newFixedThreadPool(2)){
   var fs=new ArrayList<Future<JsonNode>>();
   for(int index=0;index<2;index++){final int i=index;fs.add(pool.submit(()->{Thread.currentThread().setName("D29-HTTP-"+name+"-"+i);ready.countDown();if(!start.await(15,TimeUnit.SECONDS))throw new IllegalStateException("D29_BARREIRA_TIMEOUT");long begin=System.nanoTime();String time=Instant.now().toString();var req=HttpRequest.newBuilder(URI.create(x.base+routes.get(i))).timeout(Duration.ofSeconds(45)).header("Authorization","Bearer "+jwt).header("X-Request-Id",x.round+"-"+UUID.randomUUID()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(x.json.writeValueAsString(bodies.get(i)))).build();var response=x.http.send(req,HttpResponse.BodyHandlers.ofString());long end=System.nanoTime();timings.add(m("indice",i,"inicioUtc",time,"fimUtc",Instant.now().toString(),"inicioNano",begin,"fimNano",end,"duracaoMs",(end-begin)/1_000_000.0,"status",response.statusCode(),"RequestId",response.headers().firstValue("X-Request-Id").orElse(null)));synchronized(x){return x.recordResponse("D29 concorrencia "+name+" indice"+i,"POST",routes.get(i),bodies.get(i),"OPERACAO",200,response,competition);}}));}
   if(!ready.await(15,TimeUnit.SECONDS))throw new IllegalStateException("D29_CLIENTES_NAO_PRONTOS");String release=Instant.now().toString();start.countDown();var jvm=sampleJVM(name);var results=List.of(fs.get(0).get(60,TimeUnit.SECONDS),fs.get(1).get(60,TimeUnit.SECONDS));var statuses=timings.stream().map(t->((Number)t.get("status")).intValue()).sorted().toList();x.assertion("D29 parHTTP "+name+" conjunto esperado",statuses.equals(competition?List.of(200,409):List.of(200,200)),competition?List.of(200,409):List.of(200,200),timings);var sorted=timings.stream().sorted(Comparator.comparingLong(t->((Number)t.get("inicioNano")).longValue())).toList();boolean overlap=((Number)sorted.get(1).get("inicioNano")).longValue()<((Number)sorted.get(0).get("fimNano")).longValue();pairs.add(m("par",name,"barreiraLiberadaUtc",release,"clientesProntos",2,"tempos",new ArrayList<>(timings),"intervalosHTTPsobrepostos",overlap,"jvm",jvm,"naoProvaSQLNativo",true));x.ids.put("concorrenciaPares",pairs);x.save();return results;
  }finally{start.countDown();}
 }
 Map<String,Object> sampleJVM(String name){
  String begin=Instant.now().toString();try{
   var pb=new ProcessBuilder(java.nio.file.Path.of(System.getProperty("java.home"),"bin","jcmd.exe").toString(),Long.toString(x.app.pid()),"Thread.print","-l");pb.environment().clear();String sr=System.getenv("SystemRoot");if(sr!=null)pb.environment().put("SystemRoot",sr);var p=pb.start();String snapshot=EnsaioD29.processOutputLimited(p,8000);if(!x.secret.isEmpty())snapshot=snapshot.replace(x.secret,"[SEGREDO_OMITIDO]");var file=x.evidence.resolve("d29-"+x.round+"-jvm-"+name+".txt");java.nio.file.Files.writeString(file,snapshot);return m("arquivo",file.getFileName().toString(),"pidProprio",x.app.pid(),"inicioUtc",begin,"fimUtc",Instant.now().toString(),"capturado",true,"limite","Snapshot JVM amostrado apos barreira; nao certifica 2sessoesSQL/locks nem permanencia simultanea no servidor");
  }catch(Exception e){return m("capturado",false,"classeErro",e.getClass().getSimpleName(),"inicioUtc",begin,"limite","Timing HTTP/resultados/SELECT posterior continuam distintos de prova SQL nativa");}
 }
